function playMemeSound(win){if(!soundEnabled)return;if(!win){try{if(audioContext&&lossBuffer){const source=audioContext.createBufferSource();source.buffer=lossBuffer;source.connect(audioContext.destination);source.start()}else{let audio=document.getElementById("lossAudio");if(!audio){audio=document.createElement("audio");audio.id="lossAudio";audio.src=lossAudioData;audio.preload="auto";document.body.append(audio)}audio.currentTime=0;audio.play().catch(()=>{})}}catch(e){}return}const phrase="Chala ja! Level clear!";try{const synth=window.speechSynthesis,U=window.SpeechSynthesisUtterance;if(synth&&U){synth.cancel();const u=new U(phrase);u.lang="hi-IN";u.rate=1.08;u.pitch=1.2;u.volume=1;const voices=synth.getVoices?synth.getVoices():[];u.voice=voices.find(v=>/^hi(-|$)/i.test(v.lang))||null;synth.speak(u)}}catch(e){}if(!audioContext)primeAudio();if(!audioContext)return;[392,523,659,784].forEach((hz,i)=>{try{const t=audioContext.currentTime+i*.2,o=audioContext.createOscillator(),g=audioContext.createGain();o.type="triangle";o.frequency.setValueAtTime(hz,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.22,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.18);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.19)}catch(e){}})}function playMemeClip(win){const img=$("memeImage");img.src=win?"meme-win.jpeg":(lossCount===1?"meme-loss.jpg":"meme-loss-again.jpg");img.alt=win?"Three cartoon friends celebrating":(lossCount===1?"Three cartoon friends laughing":"A cartoon character reacting to another loss")}function burst(success){let layer=document.createElement("div");layer.className="particle-layer";for(let n=0;n<(success?14:5);n++){let p=document.createElement("span");p.className="particle"+(success?"":" miss");p.textContent=success?["?","?","?","?"][n%4]:"?";p.style.setProperty("--x",(Math.random()*280-140)+"px");p.style.setProperty("--y",(Math.random()*-180-35)+"px");p.style.setProperty("--r",(Math.random()*100-50)+"deg");layer.append(p)}document.body.append(layer);setTimeout(()=>layer.remove(),950)}function updateMap(){const host=$("levelMap");if(!host.children.length)levelData.forEach((data,i)=>{const n=i+1,b=document.createElement("button");b.type="button";b.className="level-card";b.id="level"+n;b.innerHTML="<span class=\"level-number\">"+String(n).padStart(2,"0")+"</span><span class=\"level-name\">"+data.label+"</span><span class=\"level-detail\">"+(data.seconds===12?"Warm-up":data.seconds===10?"Quick thinking":"Human speed")+" � "+data.seconds+" sec � 3 puzzles</span><span class=\"level-mark\" aria-hidden=\"true\">"+(data.label==="LOW"?"??":data.label==="MEDIUM"?"?":"??")+"</span>";b.onclick=()=>start(n);host.append(b)});for(let n=1;n<=levelData.length;n++)$("level"+n).disabled=n>unlockedLevel}$("soundToggle").onclick=()=>{soundEnabled=!soundEnabled;$("soundToggle").textContent=soundEnabled?"Sound on":"Sound off";$("soundToggle").setAttribute("aria-pressed",String(soundEnabled));if(soundEnabled){primeAudio();playMemeSound(memeWin)}};$("replayMeme").onclick=()=>{playMemeClip(memeWin);playMemeSound(memeWin)};$("retry").onclick=()=>start(activeLevel);
